def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Categories.csv'
    # Try common encodings for CSVs exported from Excel/Windows
    for enc in ['utf-8-sig', 'cp1252', 'latin1']:
        try:
            df = pd.read_csv(path, encoding=enc)
            break
        except UnicodeDecodeError:
            df = None
    if df is None:
        # last resort: replace errors
        df = pd.read_csv(path, encoding='utf-8', errors='replace')
    return pd.concat([df.head(5), df.tail(5)], ignore_index=True)

